//add #10196 ord_mainのデータ定義から外れているデータ登録・参照処理の修正 zhaoqi 20240516 start
export function getValueWithDecPointInMst(unitDecimalPoint, rstDialysisState, value) {
  if (value == null || value === '') {
    return value;
  }
  let numbers = String(value).split('.');
  let decPoint = (numbers[1]) ? numbers[1].length : 0;
  if (rstDialysisState == "0") {
    if (decPoint > unitDecimalPoint) {
      let numTemp = BigNumber(value).toFixed();
      let numSplit = numTemp.split('.');
      let amountPoint = (numSplit[1]) ? numSplit[1].length : 0;
      if (amountPoint > unitDecimalPoint) {
        value = numTemp;
      } else {
        value = BigNumber(value).toFixed(unitDecimalPoint);
      }
    } else {
      value = BigNumber(value).toFixed(unitDecimalPoint);
    }
  }

  return value;
}
//add #10196 ord_mainのデータ定義から外れているデータ登録・参照処理の修正 zhaoqi 20240516 end
